INSERT INTO _migration_611_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_waves_s3_001', 'topic_igcse_physics_waves', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A water wave has a frequency of 5.0 Hz and a wavelength of 0.60 m. Calculate the speed of the wave.', 'multiple_choice', NULL, '["A. 3.0 m/s","B. 0.12 m/s","C. 8.3 m/s","D. 30 m/s"]', 'A', 'The wave equation gives v = fλ = 5.0 × 0.60 = 3.0 m/s. (0.12 m/s divides wavelength by frequency, 8.3 m/s divides frequency by wavelength, and 30 m/s makes a power-of-ten slip when multiplying.) Therefore the correct answer is A: 3.0 m/s.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_waves_s3_002', 'topic_igcse_physics_waves', 'subj_igcse_physics', 'igcse', NULL, NULL, 'Which region of the electromagnetic spectrum has the longest wavelength?', 'multiple_choice', NULL, '["A. Gamma rays","B. Radio waves","C. Visible light","D. X-rays"]', 'B', 'The spectrum runs radio waves → microwaves → infrared → visible light → ultraviolet → X-rays → gamma rays in order of decreasing wavelength and increasing frequency, so radio waves have the longest wavelength and gamma rays the shortest. Therefore the correct answer is B: Radio waves.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_waves_s3_003', 'topic_igcse_physics_waves', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A ray of light travelling in air enters a glass block and bends towards the normal. What is this change of direction called, and why does it occur?', 'multiple_choice', NULL, '["A. Reflection, because the surface of the glass is smooth","B. Diffraction, because the ray spreads out on entering the block","C. Refraction, because light travels more slowly in glass than in air","D. Dispersion, because white light splits into colours inside the glass"]', 'C', 'Refraction is the change in direction of a wave when its speed changes at a boundary between two media. Light slows down in the optically denser glass, so the ray bends towards the normal. Reflection is bouncing off the surface, diffraction is spreading through gaps or around edges, and dispersion is the splitting of white light into colours. Therefore the correct answer is C: Refraction, because light travels more slowly in glass than in air.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igphy_waves_s3_004', 'topic_igcse_physics_waves', 'subj_igcse_physics', 'igcse', NULL, NULL, 'The critical angle for a glass–air boundary is 42°. A ray of light travelling inside the glass strikes the boundary at an angle of incidence of 50°. What happens to the ray?', 'multiple_choice', NULL, '["A. It is refracted away from the normal and leaves the glass","B. It passes straight through the boundary without bending","C. It is absorbed by the surface of the glass","D. It is totally internally reflected back into the glass"]', 'D', 'The ray is travelling from a more dense medium towards a less dense one and its angle of incidence (50°) exceeds the critical angle (42°), so no refracted ray can form and all the light is totally internally reflected. Refraction away from the normal occurs only when the angle of incidence is less than the critical angle. Therefore the correct answer is D: It is totally internally reflected back into the glass.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_waves_s3_005', 'topic_igcse_physics_waves', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A student sees a flash of lightning and hears the thunder 6.0 s later. Taking the speed of sound in air as 340 m/s, calculate the distance of the lightning strike from the student.', 'multiple_choice', NULL, '["A. 2,040 m","B. 56.7 m","C. 346 m","D. 20.4 m"]', 'A', 'Light travels so fast that its journey time is negligible, so the 6.0 s delay is the time taken by the sound: distance = speed × time = 340 × 6.0 = 2,040 m. (56.7 m divides 340 by 6.0 instead of multiplying; 346 m adds the two numbers; 20.4 m is a power-of-ten slip.) Therefore the correct answer is A: 2,040 m.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igphy_waves_s3_006', 'topic_igcse_physics_waves', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A student uses a ripple tank to investigate the properties of water waves.', 'structured', NULL, NULL, '(a) Wavelength is the distance between two adjacent points on the wave that are in phase, such as one crest and the next; frequency is the number of complete waves passing a fixed point per second, measured in hertz (Hz). (b) Wave speed v = fλ = 10 × 0.040 = 0.40 m/s. (c) In a transverse wave the oscillations are perpendicular to the direction in which the wave transfers energy — for example water ripples or light; in a longitudinal wave the oscillations are parallel to the direction of energy transfer, forming a series of compressions and rarefactions — for example sound in air.', '(a) Wavelength is the distance between two adjacent points on the wave that are in phase, such as one crest and the next; frequency is the number of complete waves passing a fixed point per second, measured in hertz (Hz). (b) Wave speed v = fλ = 10 × 0.040 = 0.40 m/s. (c) In a transverse wave the oscillations are perpendicular to the direction in which the wave transfers energy — for example water ripples or light; in a longitudinal wave the oscillations are parallel to the direction of energy transfer, forming a series of compressions and rarefactions — for example sound in air.', 'medium', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_611_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_igphy_waves_s3_006_a', 'q_igphy_waves_s3_006', 'a', 'Define the terms wavelength and frequency of a wave.', '2', 'Wavelength is the distance between two adjacent points on the wave that are in phase, such as one crest and the next; frequency is the number of complete waves passing a fixed point per second, measured in hertz (Hz).', '1'),
('sqp_q_igphy_waves_s3_006_b', 'q_igphy_waves_s3_006', 'b', 'A water wave has wavelength 0.040 m and frequency 10 Hz. Calculate the speed of the wave.', '2', 'Wave speed v = fλ = 10 × 0.040 = 0.40 m/s.', '2'),
('sqp_q_igphy_waves_s3_006_c', 'q_igphy_waves_s3_006', 'c', 'Describe the difference between a transverse wave and a longitudinal wave, giving one example of each.', '3', 'In a transverse wave the oscillations are perpendicular to the direction in which the wave transfers energy — for example water ripples or light; in a longitudinal wave the oscillations are parallel to the direction of energy transfer, forming a series of compressions and rarefactions — for example sound in air.', '3');
INSERT INTO _migration_611_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_611_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_611_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_611_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_611_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_611_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_611_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_611_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_611_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_611_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_611_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_611_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
